uint8_t         todo_today_index = 0;


void display_todolist(uint8_t direction,uint8_t browser_status)
{
    char            str_num[16];
    s32             ret;
    todolist_all_nvram_param_t todolist_all;
    todolist_content_param_t todolist_content;

    ret                 = aic_md_read(MD_ID_TOOLS_TODO,sizeof(todolist_all_nvram_param_t),&todolist_all);

    if (ret) {
        APP_LOGI("read net cfg error 0x%x\n",ret);
        }

    ret                 = aic_md_read(MD_ID_TOOLS_TODO_CONTENT,sizeof(todolist_content_param_t),&todolist_content);

    if (ret) {
        APP_LOGI("read net cfg error 0x%x\n",ret);
        }

    if (direction == 0) // up
    {
        if (browser_status == 2) {
            if (todo_today_index) {
                todo_today_index    -= 1;

                for (int8_t i = ui_FpToolsCalendarTodoSelected - 1; i >= 0; i--) {
                    if ((todolist_all.todolist[i].year == (calendar_year + 1970)) &&
                         (todolist_all.todolist[i].month == calendar_month) &&
                         (todolist_all.todolist[i].day == calendar_day)) {
                        ui_FpToolsCalendarTodoSelected = i;
                        break;
                        }
                    }
                }
            else {
                for (int8_t i = 0; i <= 9; i++) {
                    if ((todolist_all.todolist[i].year == (calendar_year + 1970)) &&
                         (todolist_all.todolist[i].month == calendar_month) &&
                         (todolist_all.todolist[i].day == calendar_day)) {
                        ui_FpToolsCalendarTodoSelected = i;
                        todo_today_index    += 1;
                        }
                    }

                todo_today_index    -= 1;
                }

            }
        else {
            if (ui_FpToolsCalendarTodoSelected) {
                ui_FpToolsCalendarTodoSelected -= 1;
                }
            else {
                for (int8_t i = 9; i >= 0; i--) {
                    if ((todolist_all.todolist[i].year >= 1970) && (todolist_all.todolist[i].year <= 2037)) {
                        ui_FpToolsCalendarTodoSelected = i;
                        break;
                        }
                    }
                }
            }
        }
    else if (direction == 1) //down
    {
        if (browser_status == 2) {
            int8_t          i;

            for (i = ui_FpToolsCalendarTodoSelected + 1; i <= 9; i++) {
                if ((todolist_all.todolist[i].year == (calendar_year + 1970)) &&
                     (todolist_all.todolist[i].month == calendar_month) &&
                     (todolist_all.todolist[i].day == calendar_day)) {
                    ui_FpToolsCalendarTodoSelected = i;
                    break;
                    }
                }

            if (i >= 10) {
                for (int8_t j = 0; j <= 9; j++) {
                    if ((todolist_all.todolist[j].year == (calendar_year + 1970)) &&
                         (todolist_all.todolist[j].month == calendar_month) &&
                         (todolist_all.todolist[j].day == calendar_day)) {
                        ui_FpToolsCalendarTodoSelected = j;
                        break;
                        }
                    }

                todo_today_index    = 0;
                }
            else 
                todo_today_index += 1;

            }
        else {
            if (ui_FpToolsCalendarTodoSelected >= 9)
                ui_FpToolsCalendarTodoSelected = 0;
            else {
                int8_t          i;

                for (i = ui_FpToolsCalendarTodoSelected + 1; i < 10; i++) {
                    if ((todolist_all.todolist[i].year >= 1970) && (todolist_all.todolist[i].year <= 2037)) {
                        ui_FpToolsCalendarTodoSelected = i;
                        break;
                        }
                    }

                if (i >= 10)
                    ui_FpToolsCalendarTodoSelected = 0;
                }
            }

        }

    if (browser_status == 2) {
        if (todo_today_index >= 9)
            sprintf(str_num,"%02d:",todo_today_index + 1);
        else {
            sprintf(str_num,"%01d:",todo_today_index + 1);
            }
        }
    else {
        if (ui_FpToolsCalendarTodoSelected >= 9)
            sprintf(str_num,"%02d:",ui_FpToolsCalendarTodoSelected + 1);
        else {
            sprintf(str_num,"%01d:",ui_FpToolsCalendarTodoSelected + 1);
            }
        }

    lv_label_set_text(ui_FpToolsCalendarTodoBrowserNumber,str_num);
    sprintf(str_num,"%04d.%02d.%02d",todolist_all.todolist[ui_FpToolsCalendarTodoSelected].year,
        todolist_all.todolist[ui_FpToolsCalendarTodoSelected].month,
        todolist_all.todolist[ui_FpToolsCalendarTodoSelected].day);
    lv_label_set_text(ui_FpToolsCalendarTodoBrowserDate,str_num);

    if (todolist_all.todolist[ui_FpToolsCalendarTodoSelected].hour == 0xff ||
         todolist_all.todolist[ui_FpToolsCalendarTodoSelected].min == 0xff) {
        lv_label_set_text(ui_FpToolsCalendarTodoBrowserTime,"");
        lv_obj_add_flag(ui_FpToolsCalendarTodoBrowserTime,LV_OBJ_FLAG_HIDDEN); /// Flags
        lv_obj_set_y(ui_FpToolsCalendarTodoBrowserContent,90);
        }
    else {
        lv_obj_clear_flag(ui_FpToolsCalendarTodoBrowserTime,LV_OBJ_FLAG_HIDDEN); /// Flags
        lv_obj_set_y(ui_FpToolsCalendarTodoBrowserContent,114);
        sprintf(str_num,"%02d:%02d",todolist_all.todolist[ui_FpToolsCalendarTodoSelected].hour,
            todolist_all.todolist[ui_FpToolsCalendarTodoSelected].min);
        lv_label_set_text(ui_FpToolsCalendarTodoBrowserTime,str_num);
        }

    lv_label_set_text(ui_FpToolsCalendarTodoBrowserContent,
        todolist_content.todo_content[ui_FpToolsCalendarTodoSelected].content);

}


uint8_t del_todolist(void) // 返回0，表示没有备忘录了
{
    s32             ret;
    todolist_all_nvram_param_t todolist_all;
    todolist_content_param_t todolist_content;

    ret                 = aic_md_read(MD_ID_TOOLS_TODO,sizeof(todolist_all_nvram_param_t),&todolist_all);

    if (ret) {
        APP_LOGI("read net cfg error 0x%x\n",ret);
        }

    ret                 = aic_md_read(MD_ID_TOOLS_TODO_CONTENT,sizeof(todolist_content_param_t),&todolist_content);

    if (ret) {
        APP_LOGI("read net cfg error 0x%x\n",ret);
        }

    int8_t          i;

    for (i = ui_FpToolsCalendarTodoSelected; i < 9; i++) {
        todolist_all.todolist[i].year = todolist_all.todolist[i + 1].year;
        todolist_all.todolist[i].month = todolist_all.todolist[i + 1].month;
        todolist_all.todolist[i].day = todolist_all.todolist[i + 1].day;
        todolist_all.todolist[i].hour = todolist_all.todolist[i + 1].hour;
        todolist_all.todolist[i].min = todolist_all.todolist[i + 1].min;
        memset(todolist_content.todo_content[i].content,0,45);
        memcpy(todolist_content.todo_content[i].content,todolist_content.todo_content[i + 1].content,45);
        }

    todolist_all.todolist[i].year = 0;
    todolist_all.todolist[i].month = 0;
    todolist_all.todolist[i].day = 0;
    todolist_all.todolist[i].hour = 0xff;
    todolist_all.todolist[i].min = 0xff;
    memset(todolist_content.todo_content[i].content,0,45);
    ret                 = aic_md_write(MD_ID_TOOLS_TODO,sizeof(todolist_all_nvram_param_t),&todolist_all);

    if (ret) {
        APP_LOGI("read net cfg error 0x%x\n",ret);
        }

    ret                 = aic_md_write(MD_ID_TOOLS_TODO_CONTENT,sizeof(todolist_content_param_t),&todolist_content);

    if (ret) {
        APP_LOGI("read net cfg error 0x%x\n",ret);
        }

    if (copy_alarm_para == (ui_FpToolsCalendarTodoSelected + 3)) {
        copy_alarm_para     = 0xff;
        aos_memset((u8 *) &copy_alarm_time,0,sizeof(aos_systime));
        }

    signed char     tt  = gx_rtc_alarm_param();

    if (tt == (ui_FpToolsCalendarTodoSelected + 3)) {
        //aos_del_alarm_time();
        reset_power_on_alarm_id();
        }

    active_recent_alarm(0);

    if (tools_calendar_todo_status == 2) // 从今日查看进入
    {
        int8_t          j   = 0;

        for (j = ui_FpToolsCalendarTodoSelected; j < TODOLIST_FLASH_MAX_COUNT; j++) {
            if ((todolist_all.todolist[j].year == (calendar_year + 1970)) &&
                 (todolist_all.todolist[j].month == calendar_month) &&
                 (todolist_all.todolist[j].day == calendar_day)) {
                ui_FpToolsCalendarTodoSelected = j;
                break;
                }
            }

        if (j >= TODOLIST_FLASH_MAX_COUNT) {
            for (j = 0; j < TODOLIST_FLASH_MAX_COUNT; j++) {
                if ((todolist_all.todolist[j].year == (calendar_year + 1970)) &&
                     (todolist_all.todolist[j].month == calendar_month) &&
                     (todolist_all.todolist[j].day == calendar_day)) {
                    ui_FpToolsCalendarTodoSelected = j;
                    todo_today_index    = 0;
                    break;
                    }
                }

            if (j >= TODOLIST_FLASH_MAX_COUNT) {
                todo_today_index    = 0;
                return 0;
                }
            }
        }
    else {
        if ((todolist_all.todolist[ui_FpToolsCalendarTodoSelected].year >= 1970) &&
             (todolist_all.todolist[ui_FpToolsCalendarTodoSelected].year <= 2037)) {
            }
        else {
            if (ui_FpToolsCalendarTodoSelected == 0)
                return 0; //没有备忘录了

            else 
                ui_FpToolsCalendarTodoSelected = 0;
            }
        }

    //display_todolist(2,tools_calendar_todo_status);
    return 1;
}


